package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamChemReactBank1 {
  private const val T = "මවුලය, රසායනික ප්‍රතික්‍රියා, අම්ල-භෂ්ම හා විද්‍යුත් රසායනය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "රසායනික ප්‍රතික්‍රියා, ස්ටොයිකියෝමිතිය හා විද්‍යුත් රසායනය පිළිබඳ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ඕනෑම ද්‍රව්‍යයක මවුල 1 ක (1 mol) අඩංගු මූලික අංශු (පරමාණු/අණු/අයන) සංඛ්‍යාව වන ඇවගාඩ්‍රෝ නියතය කොපමණද?", "6.022 × 10²³ mol⁻¹", "6.022 × 10²⁰ mol⁻¹", "3.011 × 10²³ mol⁻¹", "1.6 × 10⁻¹⁹ mol⁻¹", "මෙම සංඛ්‍යාව කාබන්-12 සමස්ථානිකයේ 12 g ක ඇති පරමාණු ගණනට සමාන වේ."),
    q("ජලයේ (H₂O) සාපේක්ෂ අණුක ස්කන්ධය කීයද? (H = 1, O = 16)", "18", "17", "34", "10", "Mᵣ(H₂O) = (1 × 2) + 16 = 18."),
    q("කැල්සියම් කාබනේට් (CaCO₃) හි සාපේක්ෂ සූත්‍ර ස්කන්ධය කීයද? (Ca = 40, C = 12, O = 16)", "100", "68", "84", "116", "40 + 12 + (16 × 3) = 40 + 12 + 48 = 100."),
    q("සෝඩියම් හයිඩ්‍රොක්සයිඩ් (NaOH) ග්‍රෑම් 80 ක අඩංගු මවුල ගණන කීයද? (Na = 23, O = 16, H = 1)", "2 mol", "1 mol", "4 mol", "0.5 mol", "NaOH හි මවුලික ස්කන්ධය 40 g mol⁻¹ බැවින් n = 80 / 40 = 2 mol."),
    q("කාබන් ඩයොක්සයිඩ් (CO₂) මවුල 0.5 ක ස්කන්ධය කොපමණද? (C = 12, O = 16)", "22 g", "44 g", "11 g", "88 g", "CO₂ හි M = 44 g mol⁻¹; ස්කන්ධය = 0.5 × 44 = 22 g."),
    q("මීතේන් (CH₄, M = 16 g mol⁻¹) ග්‍රෑම් 32 ක අඩංගු අණු සංඛ්‍යාව ඇවගාඩ්‍රෝ නියතය (L) ඇසුරින් කීයද?", "2 L", "L", "0.5 L", "4 L", "මවුල ගණන = 32 / 16 = 2 mol -> අණු 2L කි."),
    q("ග්ලූකෝස් (C₆H₁₂O₆) අණුවේ සාපේක්ෂ අණුක ස්කන්ධය කීයද? (C = 12, H = 1, O = 16)", "180", "168", "90", "360", "(6 × 12) + (12 × 1) + (6 × 16) = 72 + 12 + 96 = 180."),
    q("ඇමෝනියා (NH₃) ග්‍රෑම් 8.5 ක අඩංගු මවුල ගණන කීයද? (N = 14, H = 1)", "0.5 mol", "1.0 mol", "2.0 mol", "0.25 mol", "M(NH₃) = 17 g mol⁻¹; n = 8.5 / 17 = 0.5 mol."),
    q("2H₂ + O₂ → 2H₂O සමීකරණය අනුව ජලය මවුල 4 ක් නිපදවීමට සම්පූර්ණයෙන්ම දහනය කළ යුතු ඔක්සිජන් (O₂) මවුල ගණන කීයද?", "2 mol", "4 mol", "1 mol", "8 mol", "O₂ : H₂O අනුපාතය 1 : 2 බැවින් H₂O මවුල 4 කට O₂ මවුල 2 ක් අවශ්‍ය වේ."),
    q("CaCO₃(s) → CaO(s) + CO₂(g) ප්‍රතික්‍රියාවේදී CaCO₃ ග්‍රෑම් 50 ක් සම්පූර්ණයෙන් වියෝජනය වූ විට නිපදවෙන CaO ස්කන්ධය කීයද? (Ca=40, C=12, O=16)", "28 g", "56 g", "44 g", "22 g", "CaCO₃ 0.5 mol (50 g) වලින් CaO 0.5 mol = 0.5 × 56 = 28 g ලැබේ."),
    q("පොටෑසියම් ක්ලෝරේට් (KClO₃) රත් කිරීමෙන් ඔක්සිජන් වායුව ලබා ගැනීමේදී ප්‍රතික්‍රියාව වේගවත් කිරීමට දමන උත්ප්‍රේරකය කුමක්ද?", "මැන්ගනීස් ඩයොක්සයිඩ් (MnO₂)", "කැල්සියම් ඔක්සයිඩ්", "යකඩ කුඩු", "සෝඩියම් ක්ලෝරයිඩ්", "MnO₂ හමුවේ KClO₃ අඩු උෂ්ණත්වයකදී ඉක්මනින් වියෝජනය වේ."),
    q("CH₄ + 2O₂ → CO₂ + 2H₂O ප්‍රතික්‍රියාවේදී මීතේන් මවුල 1 ක් පූර්ණ දහනයට අවශ්‍ය O₂ ස්කන්ධය කීයද? (O = 16)", "64 g", "32 g", "16 g", "128 g", "O₂ මවුල 2 ක් අවශ්‍ය වේ; 2 × 32 g = 64 g."),
    q("සක්‍රියතා ශ්‍රේණියේ ඉහළින්ම පිහිටි ලෝහය වන්නේ පහත සඳහන් කවරෙක්ද?", "පොටෑසියම් (K)", "මැග්නීසියම් (Mg)", "යකඩ (Fe)", "තඹ (Cu)", "K > Na > Ca > Mg > Al > Zn > Fe > Pb > H > Cu > Ag > Au."),
    q("තනුක හයිඩ්‍රොක්ලෝරික් අම්ලය (HCl) සමඟ ප්‍රතික්‍රියා කර හයිඩ්‍රජන් වායුව පිට නොකරන ලෝහය කුමක්ද?", "තඹ (Cu)", "සින්ක් (Zn)", "මැග්නීසියම් (Mg)", "යකඩ (Fe)", "සක්‍රියතා ශ්‍රේණියේ හයිඩ්‍රජන්ට පහළින් ඇති Cu, Ag, Au තනුක අම්ල සමඟ H₂ නොසාදයි."),
    q("කොපර්(II) සල්ෆේට් (CuSO₄) නිල් ද්‍රාවණයකට යකඩ ඇණයක් දැමූ විට සිදුවන නිරීක්ෂණය කුමක්ද?", "ඇණය මත තඹ තැන්පත් වී ද්‍රාවණය ලා කොළ වේ", "ද්‍රාවණයේ හෝ ඇණයේ කිසිදු වෙනසක් සිදු නොවේ", "ද්‍රාවණයේ නිල් පැහැය තවදුරටත් තද පැහැ වේ", "ද්‍රාවණයෙන් කළු පැහැති වායුවක් පිට වේ", "Fe සක්‍රියතාව Cu ට වඩා වැඩි බැවින් Fe + CuSO₄ → FeSO₄ + Cu සිදුවේ."),
    q("Zn + H₂SO₄ → ZnSO₄ + H₂ යන ප්‍රතික්‍රියාව අයත් වන්නේ කුමන ප්‍රතික්‍රියා වර්ගයටද?", "ඒක විස්ථාපන ප්‍රතික්‍රියාව", "සංයෝජන ප්‍රතික්‍රියාව", "වියෝජන ප්‍රතික්‍රියාව", "ද්විත්ව විස්ථාපන ප්‍රතික්‍රියාව", "වැඩි සක්‍රීය Zn අම්ලයේ හයිඩ්‍රජන් විස්ථාපනය කරයි."),
    q("රිදී නයිට්‍රේට් (AgNO₃) ද්‍රාවණයකට සෝඩියම් ක්ලෝරයිඩ් (NaCl) දැමූ විට සුදු අවක්ෂේපයක් (AgCl) සෑදීම කුමන ප්‍රතික්‍රියා වර්ගයක්ද?", "ද්විත්ව විස්ථාපන (අවක්ෂේපන) ප්‍රතික්‍රියාව", "වියෝජන ප්‍රතික්‍රියාව", "සංයෝජන ප්‍රතික්‍රියාව", "දාහ ප්‍රතික්‍රියාව", "AgNO₃ + NaCl → AgCl↓ + NaNO₃."),
    q("දහන ප්‍රතික්‍රියාවකට (Combustion) අවශ්‍ය අංග තුන (ගිනි ත්‍රිකෝණය) මොනවාද?", "ඉන්ධනය, ඔක්සිජන් (වාතය) සහ ජ්වලන උෂ්ණත්වය", "ඉන්ධනය, ජලය හා කාබන් ඩයොක්සයිඩ්", "ඔක්සිජන්, නයිට්‍රජන් හා හීලියම්", "තාපය, ආලෝකය හා අළු", "මෙම සාධක තුනෙන් ඕනෑම එකක් ඉවත් කිරීමෙන් ගින්නක් නිවා දැමිය හැක."),
    q("විදුලි උපකරණ හෝ තෙල් නිසා හටගන්නා ගින්නක් නිවීම සඳහා ජලය භාවිත නොකළ යුත්තේ ඇයි?", "තෙල් ජලයේ පාවී ගින්න පැතිරීම හා විදුලි සැර වැදීම", "ජලය ඉහළ උෂ්ණත්වයේදී ගිනි ගන්නා ද්‍රවයක් වීම", "ජලය තාපය හමුවේ ඔක්සිජන් වායුව නිපදවන නිසා", "ජලය ඉතා සීතල ද්‍රවයක් බැවින් ගින්න වැඩි වීම", "විදුලි ගිනි නිවීමට CO₂ හෝ වියළි කුඩු ගිනි නිවන උපකරණ යොදා ගනී."),
    q("රසායනික ප්‍රතික්‍රියාවක සීඝ්‍රතාව වැඩි කිරීමට බලපාන සාධකයක් නොවන්නේ කුමක්ද?", "ප්‍රතික්‍රියා පාත්‍රයේ වර්ණය", "ප්‍රතික්‍රියකවල උෂ්ණත්වය", "ප්‍රතික්‍රියකවල පෘෂ්ඨ වර්ගඵලය", "උත්ප්‍රේරක භාවිතය", "සාන්ද්‍රණය, උෂ්ණත්වය, පෘෂ්ඨ වර්ගඵලය හා උත්ප්‍රේරක ප්‍රතික්‍රියා සීඝ්‍රතාව වැඩි කරයි."),
    q("හුණුගල් කුට්ටි වෙනුවට හුණුගල් කුඩු සමාන ස්කන්ධයක් HCl අම්ලය සමඟ ප්‍රතික්‍රියා කළ විට ප්‍රතික්‍රියාව වේගවත් වන්නේ ඇයි?", "පෘෂ්ඨ වර්ගඵලය වැඩි වී ගැටුම් සංඛ්‍යාතය වැඩි වීම", "හුණුගල් කුඩු කළ විට අණුවල අභ්‍යන්තර ශක්තිය වැඩි වීම", "භාවිත කරන HCl අම්ලයේ සාන්ද්‍රණය ඉබේම වැඩි වීම", "ප්‍රතික්‍රියාවෙන් පිටවන මුළු CO₂ පරිමාව දෙගුණ වීම", "ඒකක කාලයකදී අංශු අතර සිදුවන සඵල ගැටුම් ගණන වැඩි වේ."),
    q("රසායනික ප්‍රතික්‍රියාවකදී උත්ප්‍රේරකයක් (Catalyst) සිදු කරන කාර්යය කුමක්ද?", "අඩු සක්‍රීයන ශක්ති මාර්ගයකින් සීඝ්‍රතාව වැඩි කිරීම", "ප්‍රතික්‍රියාවෙන් ලැබෙන අවසන් ඵල ප්‍රමාණය දෙගුණ කිරීම", "ප්‍රතික්‍රියාව අතරතුරදී සම්පූර්ණයෙන්ම වැය වී යාම", "ප්‍රතික්‍රියාවේ මුළු එන්තැල්පි විපර්යාසය වෙනස් කිරීම", "ප්‍රතික්‍රියාව අවසානයේදී උත්ප්‍රේරකය රසායනිකව නොවෙනස්ව ඉතිරි වේ."),
    q("තාපදායක (Exothermic) ප්‍රතික්‍රියාවකදී පද්ධතියේ එන්තැල්පි විපර්යාසය (ΔH) හා පරිසර උෂ්ණත්වයට කුමක් සිදුවේද?", "ΔH සෘණ වන අතර අවට උෂ්ණත්වය ඉහළ යයි", "ΔH ධන වන අතර අවට උෂ්ණත්වය පහළ බසී", "එන්තැල්පි විපර්යාසය සැමවිටම ශුන්‍ය වේ", "අවට පරිසරයෙන් පද්ධතියට තාපය අවශෝෂණය වේ", "උදාසීනීකරණ හා දහන ප්‍රතික්‍රියා සියල්ල තාපදායක වේ."),
    q("ඇමෝනියම් නයිට්‍රේට් (NH₄NO₃) ජලයේ දිය කළ විට බීකරය සිසිල් වේ. මෙම ක්‍රියාවලිය කුමක්ද?", "තාප අවශෝෂක ක්‍රියාවලියකි", "තාපදායක රසායනික ක්‍රියාවලියකි", "වේගවත් ඔක්සිකරණ දහනයකි", "විද්‍යුත් විච්ඡේදන ක්‍රියාවලියකි", "පරිසරයෙන් හා ජලයෙන් තාපය උරා ගන්නා බැවින් උෂ්ණත්වය පහළ බසී."),
    q("ආරේනියස් අර්ථ දැක්වීමට අනුව 'අම්ලයක්' (Acid) යනු ජලීය ද්‍රාවණයේදී කුමන අයන නිදහස් කරන ද්‍රව්‍යයක්ද?", "හයිඩ්‍රජන් අයන (H⁺ / H₃O⁺)", "හයිඩ්‍රොක්සයිඩ් අයන (OH⁻)", "සෝඩියම් අයන (Na⁺)", "ක්ලෝරයිඩ් අයන (Cl⁻)", "ප්‍රබල අම්ල ජලයේදී 100% ක් H⁺ අයන බවට අයනීකරණය වේ."),
    q("දෙහි යුෂ හා විනාකිරිවල අඩංගු වන දුබල කාබනික අම්ල පිළිවෙළින් මොනවාද?", "සිට්‍රික් අම්ලය සහ ඇසිටික් අම්ලය", "සල්ෆියුරික් අම්ලය සහ නයිට්‍රික් අම්ලය", "හයිඩ්‍රොක්ලෝරික් අම්ලය සහ ෆෝමික් අම්ලය", "ලැක්ටික් අම්ලය සහ ඔක්සැලික් අම්ලය", "විනාකිරි යනු 4–5% පමණ ඇසිටික් (එතනොයික්) අම්ල ද්‍රාවණයකි."),
    q("ජලීය ද්‍රාවණයකදී අර්ධ වශයෙන් අයනීකරණය වන 'දුබල අම්ලයකට' උදාහරණය කුමක්ද?", "ඇසිටික් අම්ලය (CH₃COOH)", "හයිඩ්‍රොක්ලෝරික් අම්ලය (HCl)", "සල්ෆියුරික් අම්ලය (H₂SO₄)", "නයිට්‍රික් අම්ලය (HNO₃)", "HCl, H₂SO₄ සහ HNO₃ ප්‍රබල අකාබනික අම්ල වේ."),
    q("නිල් ලිට්මස් කඩදාසියක් රතු පැහැයට හරවන ද්‍රාවණයක pH අගය කෙබඳු විය හැකිද?", "pH අගය 7 ට වඩා අඩුය", "pH අගය හරියටම 7 කි", "pH අගය 7 ට වඩා වැඩිය", "pH අගය සැමවිටම 14 කි", "අම්ල නිල් ලිට්මස් රතු පැහැ ගන්වයි."),
    q("ෆීනෝල්ෆ්තැලීන් දර්ශකය ප්‍රබල භාෂ්මික ද්‍රාවණයකදී (උදා: NaOH) පෙන්වන වර්ණය කුමක්ද?", "රෝස / තද දම් රතු පැහැය", "අවර්ණ පැහැය", "නිල් පැහැය", "කහ පැහැය", "ආම්ලික හා උදාසීන මාධ්‍යවල ෆීනෝල්ෆ්තැලීන් අවර්ණ වේ."),
    q("මෙතිල් ඔරේන්ජ් දර්ශකය ආම්ලික ද්‍රාවණයකදී හා භාෂ්මික ද්‍රාවණයකදී පෙන්වන වර්ණ පිළිවෙළින් මොනවාද?", "ආම්ලික විට රතු / රෝස, භාෂ්මික විට කහ", "ආම්ලික විට කහ, භාෂ්මික විට රතු", "ආම්ලික විට නිල්, භාෂ්මික විට කොළ", "දෙකේදීම අවර්ණ", "මෙය අම්ල-භෂ්ම අනුමාපනවලදී බහුලව භාවිත කෙරේ."),
    q("ආමාශයේ අධික ආම්ලිකතාව (ගැස්ට්‍රයිටිස්) සමනය කිරීමට භාවිත කරන 'මැග්නීසියා ක්ෂීර' (Milk of magnesia) හි අඩංගු ප්‍රතිඅම්ල භෂ්මය කුමක්ද?", "මැග්නීසියම් හයිඩ්‍රොක්සයිඩ් (Mg(OH)₂)", "සෝඩියම් හයිඩ්‍රොක්සයිඩ් (NaOH)", "පොටෑසියම් හයිඩ්‍රොක්සයිඩ් (KOH)", "සල්ෆියුරික් අම්ලය", "Mg(OH)₂ මෘදු දුබල භෂ්මයක් බැවින් අධික අම්ලය උදාසීන කරයි; NaOH දැඩි විඛාදකයකි."),
    q("HCl(aq) + NaOH(aq) → NaCl(aq) + H₂O(l) ප්‍රතික්‍රියාව හඳුන්වන්නේ කුමන නමින්ද?", "උදාසීනීකරණ ප්‍රතික්‍රියාව", "ඔක්සිකරණ ප්‍රතික්‍රියාව", "වියෝජන ප්‍රතික්‍රියාව", "අවක්ෂේපන ප්‍රතික්‍රියාව", "අම්ලයක් හා භෂ්මයක් ප්‍රතික්‍රියා කර ලවණය හා ජලය සෑදීම උදාසීනීකරණයයි."),
    q("තනුක අම්ලයක් ලෝහ කාබනේටයක් (උදා: CaCO₃) සමඟ ප්‍රතික්‍රියා කළ විට නිපදවෙන ඵල මොනවාද?", "ලවණය, ජලය සහ කාබන් ඩයොක්සයිඩ්", "ලවණය සහ හයිඩ්‍රජන් පමණි", "භෂ්මය සහ ඔක්සිජන්", "ලවණය සහ ඇමෝනියා", "CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂."),
    q("පිටවන වායුවක් හුනු දියර (Ca(OH)₂) කිරි පැහැයට හැරවුවහොත් එම වායුව කුමක්ද?", "කාබන් ඩයොක්සයිඩ් (CO₂)", "හයිඩ්‍රජන් (H₂)", "ඔක්සිජන් (O₂)", "ඇමෝනියා (NH₃)", "දිය නොවන CaCO₃ අවක්ෂේපය සෑදීම නිසා කිරි පැහැ වේ."),
    q("දැල්වෙන ගිනිකූරක් පරීක්ෂණ නළයක කට ළඟට ඇල්ලූ විට 'පොප්' හඬින් පිපිරී යන වායුව කුමක්ද?", "හයිඩ්‍රජන් (H₂)", "ඔක්සිජන් (O₂)", "කාබන් ඩයොක්සයිඩ් (CO₂)", "නයිට්‍රජන් (N₂)", "හයිඩ්‍රජන් වාතයේ ඇති ඔක්සිජන් සමඟ ක්ෂණිකව දහනය වී පොප් හඬ නගයි."),
    q("අඩු ආලෝකයකින් දැල්වෙන හෝ නිවුණු පහන් කූරක් නැවත දල්වා ගැනීමට සමත් වායුව කුමක්ද?", "ඔක්සිජන් (O₂)", "හයිඩ්‍රජන් (H₂)", "කාබන් ඩයොක්සයිඩ් (CO₂)", "හීලියම් (He)", "ඔක්සිජන් දහනයට අනුබල දෙන වායුවකි."),
    q("ඔක්සිකරණ-ඔක්සිහරණ ප්‍රතික්‍රියාවකදී (Redox) ඉලෙක්ට්‍රෝන අර්ථ දැක්වීම අනුව 'ඔක්සිකරණය' යනු කුමක්ද?", "පරමාණුවකින් හෝ අයනයකින් ඉලෙක්ට්‍රෝන ඉවත් වීම (පිට කිරීම)", "ඉලෙක්ට්‍රෝන ලබා ගැනීම", "හයිඩ්‍රජන් ලබා ගැනීම", "ඔක්සිජන් ඉවත් කිරීම", "OIL RIG: Oxidation Is Loss of electrons, Reduction Is Gain of electrons."),
    q("CuO + H₂ → Cu + H₂O ප්‍රතික්‍රියාවේදී ඔක්සිහරණය වී ඇති ද්‍රව්‍යය සහ ඔක්සිහාරකය පිළිවෙළින් මොනවාද?", "CuO ඔක්සිහරණය වේ; H₂ ඔක්සිහාරකයයි", "H₂ ඔක්සිහරණය වේ; CuO ඔක්සිහාරකයයි", "Cu ඔක්සිකරණය වේ", "H₂O ඔක්සිකාරකයයි", "CuO වලින් ඔක්සිජන් ඉවත් වී Cu බවට ඔක්සිහරණය වේ."),
    q("විද්‍යුත් විච්ඡේදක කෝෂයකදී ඔක්සිකරණය සිදු වන්නේ කුමන ඉලෙක්ට්‍රෝඩයේද?", "ඇනෝඩයේදී (ධන ඉලෙක්ට්‍රෝඩයේ)", "කැතෝඩයේදී (සෘණ ඉලෙක්ට්‍රෝඩයේ)", "ද්‍රාවණය මැදදී", "කෝෂයෙන් පිටතදී", "විද්‍යුත් විච්ඡේදක හා විද්‍යුත් රසායනික කෝෂ දෙකෙහිම ඇනෝඩයේ ඔක්සිකරණයත් කැතෝඩයේ ඔක්සිහරණයත් සිදුවේ."),
    q("විද්‍යුත් රසායනික (ගැල්වැනික) කෝෂයක් වන Zn | Zn²⁺ || Cu²⁺ | Cu සරල කෝෂයේ සෘණ අග්‍රය (ඇනෝඩය) වන්නේ කුමන ලෝහයද?", "සින්ක් (Zn)", "තඹ (Cu)", "දෙකම ධන අග්‍ර වේ", "ප්ලැටිනම්", "වැඩි සක්‍රීය ලෝහය (Zn) ඉලෙක්ට්‍රෝන මුදා හැර Zn²⁺ බවට ඔක්සිකරණය වී සෘණ අග්‍රය සාදයි."),
    q("සරල වෝල්ටා කෝෂයක තනුක H₂SO₄ අම්ලය තුළ සින්ක් හා තඹ තහඩු ගිල්වූ විට තඹ තහඩුව මත පිටවන වායු බුබුළු මොනවාද?", "හයිඩ්‍රජන් (H₂)", "ඔක්සිජන් (O₂)", "සල්ෆර් ඩයොක්සයිඩ්", "කාබන් ඩයොක්සයිඩ්", "බාහිර පරිපථය හරහා එන ඉලෙක්ට්‍රෝන H⁺ අයන විසින් ලබාගෙන H₂ ලෙස පිටවේ."),
    q("වියළි කෝෂයක (Dry cell) ධන අග්‍රය ලෙස භාවිත කරන සන්නායක දණ්ඩ කුමක්ද?", "කාබන් (මිනිරන්) දණ්ඩ", "සින්ක් ආවරණය", "ඊයම් තහඩුව", "තඹ කම්බිය", "වියළි කෝෂයේ සින්ක් බඳුන සෘණ අග්‍රය වන අතර ඇමෝනියම් ක්ලෝරයිඩ් පේස්ට් එක විද්‍යුත් විච්ඡේද්‍යයයි."),
    q("මෝටර් රථ බැටරි වැනි නැවත ආරෝපණය කළ හැකි 'ඊයම්-අම්ල ඇකියුමියුලේටරයේ' භාවිත කරන විද්‍යුත් විච්ඡේද්‍යය කුමක්ද?", "තනුක සල්ෆියුරික් අම්ලය (H₂SO₄)", "සෝඩියම් ක්ලෝරයිඩ් ද්‍රාවණය", "ඇමෝනියම් ක්ලෝරයිඩ්", "නයිට්‍රික් අම්ලය", "Pb සහ PbO₂ ඉලෙක්ට්‍රෝඩ H₂SO₄ තුළ ගිල්වා ඇත."),
    q("යකඩ මලකඩ කෑම (Rusting) සිදුවීමට අනිවාර්යයෙන්ම පැවතිය යුතු සාධක දෙක මොනවාද?", "ඔක්සිජන් සහ ජලය (තෙතමනය)", "නයිට්‍රජන් සහ කාබන් ඩයොක්සයිඩ්", "හිරු එළිය සහ වැලි", "හීලියම් සහ පීඩනය", "යකඩ මලකඩ යනු සජල ෆෙරික් ඔක්සයිඩ් (Fe₂O₃·xH₂O) වේ."),
    q("යකඩ වානේ පාලම් හා නැව් බඳ මලකඩ කෑමෙන් ආරක්ෂා කිරීම සඳහා සින්ක් හෝ මැග්නීසියම් කුට්ටි සවි කිරීමේ ක්‍රමය කුමක්ද?", "කැපකිරීමේ කැතෝඩික ආරක්ෂණය", "සාමාන්‍ය තෙල් තීන්ත ආලේප කිරීම", "මතුපිට ඝන ග්‍රීස් ස්තරයක් ගෑම", "විද්‍යුත් විලේපන ක්‍රියාවලිය", "වැඩි සක්‍රීය Zn හෝ Mg යකඩ වෙනුවට ඔක්සිකරණය වී යකඩ රැක දෙයි."),
    q("යකඩ පත්‍ර මත ගැල්වනයිස් කිරීමේදී (Galvanizing) ආලේප කරන ලෝහය කුමක්ද?", "සින්ක් (Zn)", "තඹ (Cu)", "රන් (Au)", "ඊයම් (Pb)", "සින්ක් ස්තරය සීරුණ ද කැතෝඩික ආරක්ෂණයෙන් යකඩ රැකේ."),
    q("ආම්ලික කොපර් සල්ෆේට් (CuSO₄) ද්‍රාවණයක් තඹ ඉලෙක්ට්‍රෝඩ යොදා විද්‍යුත් විච්ඡේදනය කළ විට ඇනෝඩයේදී සිදුවන ක්‍රියාව කුමක්ද?", "තඹ ඇනෝඩය Cu²⁺ අයන ලෙස දිය වී ක්ෂය වීම", "තඹ තැන්පත් වීම", "හයිඩ්‍රජන් පිටවීම", "ක්ලෝරීන් පිටවීම", "අපිරිසිදු තඹ පිරිපහදු කිරීමේදී හා තඹ ආලේප කිරීමේදී මෙය භාවිත කෙරේ."),
    q("විද්‍යුත් ආලේපනයේදී (Electroplating) ආලේප කිරීමට අවශ්‍ය වස්තුව (උදා: යකඩ හැන්ද) සම්බන්ධ කළ යුත්තේ කුමන අග්‍රයටද?", "කැතෝඩයට (සෘණ අග්‍රයට)", "ඇනෝඩයට (ධන අග්‍රයට)", "බැටරියෙන් පිටතට", "ඕනෑම අග්‍රයකට", "ද්‍රාවණයේ ඇති ලෝහ කැටායන කැතෝඩය වෙත ආකර්ෂණය වී එහි තැන්පත් වේ."),
    q("විලීන සෝඩියම් ක්ලෝරයිඩ් (NaCl(l)) නිෂ්ක්‍රීය කාබන් ඉලෙක්ට්‍රෝඩ අතර විද්‍යුත් විච්ඡේදනය කළ විට කැතෝඩයේදී ලැබෙන ඵලය කුමක්ද?", "සෝඩියම් ලෝහය (Na)", "හයිඩ්‍රජන් වායුව (H₂)", "ක්ලෝරීන් වායුව (Cl₂)", "ඔක්සිජන් වායුව (O₂)", "විලීන NaCl තුළ ජලය නොමැති බැවින් Na⁺ කෙළින්ම Na බවට ඔක්සිහරණය වේ."),
    q("සාන්ද්‍ර ජලීය NaCl (Brine) ද්‍රාවණයක් නිෂ්ක්‍රීය ඉලෙක්ට්‍රෝඩ යොදා විද්‍යුත් විච්ඡේදනය කළ විට කැතෝඩයේදී පිටවන වායුව කුමක්ද?", "හයිඩ්‍රජන් (H₂)", "සෝඩියම් ලෝහය", "ක්ලෝරීන් (Cl₂)", "ඔක්සිජන් (O₂)", "Na⁺ ට වඩා H⁺ පහසුවෙන් ඔක්සිහරණය වන නිසා H₂ පිටවේ; ඇනෝඩයේදී Cl₂ පිටවේ."),
    q("ආම්ලීකරණය කළ ජලය (Acidified water) ප්ලැටිනම් ඉලෙක්ට්‍රෝඩ යොදා විද්‍යුත් විච්ඡේදනය කළ විට කැතෝඩයේ හා ඇනෝඩයේ ලැබෙන වායු පරිමා අනුපාතය කීයද?", "H₂ : O₂ = 2 : 1", "H₂ : O₂ = 1 : 2", "H₂ : O₂ = 1 : 1", "H₂ : O₂ = 4 : 1", "ජල අණුවේ (H₂O) හයිඩ්‍රජන් හා ඔක්සිජන් අනුපාතය 2 : 1 බැවිනි."),
    q("කැල්සියම් ඔක්සයිඩ් (පිළිස්සූ හුණු / CaO) ජලය සමඟ ප්‍රතික්‍රියා කර නිවූ හුණු (Ca(OH)₂) සෑදීමේදී දක්නට ලැබෙන විශේෂ ලක්ෂණය කුමක්ද?", "අධික තාපයක් පිටවන තාපදායක වීම", "මිශ්‍රණයේ ඇති ජලය අයිස් බවට මිදී යාම", "ලා නිල් පැහැති වායුවක් පිටතට පැමිණීම", "කාබන් ඩයොක්සයිඩ් බුබුළු පිටවීම", "CaO + H₂O → Ca(OH)₂ + තාපය."),
    q("C₃H₈ + 5O₂ → 3CO₂ + 4H₂O ප්‍රතික්‍රියාව අනුව ප්‍රොපේන් (C₃H₈) මවුල 2 ක් සම්පූර්ණයෙන් දහනය කළ විට සෑදෙන CO₂ මවුල ගණන කීයද?", "6 mol", "3 mol", "8 mol", "10 mol", "C₃H₈ : CO₂ = 1 : 3 බැවින් මවුල 2 කින් මවුල 6 ක් ලැබේ."),
    q("කිසියම් ලවණයක් වන CuSO₄·5H₂O නිල් ස්ඵටික තදින් රත් කළ විට සිදුවන වර්ණ විපර්යාසය කුමක්ද?", "නිල් පැහැයේ සිට සුදු පැහැයට හැරීම", "සුදු සිට නිල් පැහැයට", "කොළ සිට කළු පැහැයට", "තැඹිලි සිට කොළ පැහැයට", "ස්ඵටික ජලය වාෂ්ප වීමෙන් නිර්ජලීය CuSO₄ (සුදු) සෑදේ."),
    q("ඉටිපන්දමක් දහනය වීමේදී ඉටි දිය වීම සහ ඉටි වාෂ්පය දැල්වීම පිළිවෙළින් කුමන වෙනස්වීම්ද?", "භෞතික වෙනසක් සහ රසායනික වෙනසක්", "දෙකම භෞතික වෙනස්වීම්", "දෙකම රසායනික වෙනස්වීම්", "රසායනික සහ භෞතික වෙනසක්", "දිය වීමේදී නව ද්‍රව්‍ය නොසෑදෙන අතර දහනයේදී CO₂ හා H₂O නව ද්‍රව්‍ය ලෙස සෑදේ."),
    q("පහත දැක්වෙන අම්ල අතුරින් ද්විභාෂ්මික (Dibasic) අම්ලයක් වන්නේ කුමක්ද?", "සල්ෆියුරික් අම්ලය (H₂SO₄)", "හයිඩ්‍රොක්ලෝරික් අම්ලය (HCl)", "නයිට්‍රික් අම්ලය (HNO₃)", "ඇසිටික් අම්ලය (CH₃COOH)", "H₂SO₄ අණුවකින් විස්ථාපනය කළ හැකි H⁺ අයන 2 ක් ලබා දෙයි."),
    q("පසේ ආම්ලිකතාව ඉතා අධික වූ විට එය නිවැරදි කිරීමට ගොවීන් පසට එක් කරන සංයෝගය කුමක්ද?", "අළු හුණු හෝ කැල්සියම් කාබනේට්", "නයිට්‍රජන් බහුල යූරියා පොහොර", "සාන්ද්‍ර සල්ෆියුරික් අම්ල ද්‍රාවණය", "ඇමෝනියම් සල්ෆේට් රසායනික ලවණය", "භාෂ්මික කැල්සියම් සංයෝග පසේ අම්ල උදාසීන කරයි."),
    q("ඇමෝනියම් ක්ලෝරයිඩ් (NH₄Cl) සහ සෝඩියම් හයිඩ්‍රොක්සයිඩ් (NaOH) එක් කර රත් කළ විට පිටවන තියුණු ගඳැති වායුව කුමක්ද?", "ඇමෝනියා (NH₃)", "ක්ලෝරීන්", "නයිට්‍රජන්", "හයිඩ්‍රජන්", "NH₃ තෙත් රතු ලිට්මස් නිල් පැහැයට හරවන ක්ෂාරීය වායුවකි."),
    q("කිසියම් ද්‍රව්‍යයක් වන Na₂CO₃ හි සාපේක්ෂ සූත්‍ර ස්කන්ධය කීයද? (Na = 23, C = 12, O = 16)", "106", "83", "100", "74", "(2 × 23) + 12 + (3 × 16) = 46 + 12 + 48 = 106."),
    q("මැග්නීසියම් 12 g ක් අතිරික්ත තනුක HCl සමඟ සම්පූර්ණයෙන් ප්‍රතික්‍රියා කළ විට නිපදවෙන H₂ වායු මවුල ගණන කීයද? (Mg = 24)", "0.5 mol", "1.0 mol", "2.0 mol", "0.25 mol", "Mg + 2HCl → MgCl₂ + H₂; Mg 0.5 mol (12/24) වලින් H₂ මවුල 0.5 ක් ලැබේ."),
    q("පොටෑසියම් අයඩයිඩ් (KI) හා ලෙඩ් නයිට්‍රේට් (Pb(NO₃)₂) ජලීය ද්‍රාවණ දෙකක් මිශ්‍ර කළ විට සෑදෙන අවක්ෂේපයේ වර්ණය කුමක්ද?", "දීප්තිමත් කහ පැහැති අවක්ෂේපය (PbI₂)", "සුදු අවක්ෂේපය", "නිල් අවක්ෂේපය", "කළු අවක්ෂේපය", "ලෙඩ් අයඩයිඩ් (PbI₂) යනු දීප්තිමත් කහ පැහැති අවක්ෂේපයකි."),
    q("මවුලික ස්කන්ධය 2 g mol⁻¹ වූ හයිඩ්‍රජන් වායුව (H₂) ග්‍රෑම් 6 ක අඩංගු හයිඩ්‍රජන් පරමාණු මවුල සංඛ්‍යාව කීයද?", "6 mol", "3 mol", "2 mol", "12 mol", "H₂ අණු මවුල = 6/2 = 3 mol; එක් H₂ අණුවක H පරමාණු 2 ක් ඇති බැවින් H පරමාණු 6 mol වේ."),
    q("ස්කන්ධ සංස්ථිති නියමයට (Law of conservation of mass) අනුව සංවෘත පද්ධතියක රසායනික ප්‍රතික්‍රියාවකදී සිදු වන්නේ කුමක්ද?", "ප්‍රතික්‍රියකවල මුළු ස්කන්ධය ඵලවල ස්කන්ධයට සමාන වේ", "ප්‍රතික්‍රියාවෙන් පසු මුළු ස්කන්ධය සැමවිටම අඩු වේ", "ප්‍රතික්‍රියාව අවසානයේ මුළු ස්කන්ධය දෙගුණයක් වේ", "පවතින මූලද්‍රව්‍ය පරමාණු සම්පූර්ණයෙන් විනාශ වේ", "ප්‍රතික්‍රියාවකදී පරමාණු නැවත සැකසීමක් පමණක් සිදු වේ."),
    q("Ca + 2H₂O → Ca(OH)₂ + H₂ ප්‍රතික්‍රියාවෙන් පෙන්වන ලෝහයේ ගුණය කුමක්ද?", "කැල්සියම් සිසිල් ජලය සමඟ H₂ පිට කරයි", "කැල්සියම් කිසිදු ජලයක් සමඟ ප්‍රතික්‍රියා නොකරයි", "කැල්සියම් තනුක අම්ල සමඟ පමණක් ප්‍රතික්‍රියා කරයි", "කැල්සියම් ජලය සමඟ ඔක්සිජන් වායුව පිට කරයි", "මැග්නීසියම් සිසිල් ජලය සමඟ ඉතා සෙමෙන් වුවද උණු ජලය/හුමාලය සමඟ වේගයෙන් ප්‍රතික්‍රියා කරයි."),
    q("තඹ ඔක්සයිඩ් (CuO - කළු) හා තනුක සල්ෆියුරික් අම්ලය රත් කර ප්‍රතික්‍රියා කළ විට ලැබෙන ද්‍රාවණයේ වර්ණය කුමක්ද?", "නිල් පැහැය (CuSO₄)", "ලා කොළ පැහැය", "රෝස පැහැය", "අවර්ණ", "CuO + H₂SO₄ → CuSO₄ + H₂O."),
    q("සෝඩියම් හයිඩ්‍රොක්සයිඩ් හා HCl අතර උදාසීනීකරණ ප්‍රතික්‍රියාවේදී ද්‍රාවණයේ උෂ්ණත්වය මැන බැලීමට කළ පරීක්ෂණයකදී උෂ්ණත්වය 25°C සිට 31°C දක්වා ඉහළ ගියේය. තාප හුවමාරුව කෙබඳුද?", "ප්‍රතික්‍රියාව මගින් ජලයට තාපය මුදා හැර ඇත (තාපදායක)", "ජලයෙන් තාපය උරා ගෙන ඇත", "තාප විපර්යාසය ශුන්‍ය වේ", "ද්‍රාවණය සිසිල් වී ඇත", "Q = mcΔθ ඇසුරින් උදාසීනීකරණ තාපය ගණනය කළ හැක."),
    q("කිසියම් ලෝහ ඔක්සයිඩයක් වන Fe₂O₃ යකඩ නිස්සාරණයේදී කාබන් මොනොක්සයිඩ් (CO) මගින් Fe බවට පත් වීමේදී Fe₂O₃ ට සිදු වන්නේ කුමක්ද?", "ඔක්සිහරණය වීම", "ඔක්සිකරණය වීම", "ජලවිච්ඡේදනය", "උදාසීනීකරණය", "Fe₂O₃ + 3CO → 2Fe + 3CO₂."),
    q("H₂SO₄ අණුවක (M = 98 g mol⁻¹) සල්ෆර් (S = 32) අඩංගු ස්කන්ධ ප්‍රතිශතය ආසන්න වශයෙන් කීයද?", "32.7%", "50.0%", "65.3%", "16.0%", "(32 / 98) × 100% ≈ 32.65%."),
    q("ඇමෝනියා (NH₃, M = 17) හි නයිට්‍රජන් (N = 14) ස්කන්ධ ප්‍රතිශතය කොපමණද?", "82.4%", "17.6%", "50.0%", "64.0%", "(14 / 17) × 100% ≈ 82.35%."),
    q("පොටෑසියම් (K), කැල්සියම් (Ca), ඇලුමිනියම් (Al) සහ රන් (Au) අතුරින් ජලය, හුමාලය හෝ තනුක අම්ල සමඟ කිසිසේත් ප්‍රතික්‍රියා නොකරන ලෝහය කුමක්ද?", "රන් (Au)", "පොටෑසියම් (K)", "කැල්සියම් (Ca)", "ඇලුමිනියම් (Al)", "රන් හා ප්ලැටිනම් ඉතා නිෂ්ක්‍රීය 'රාජකීය ලෝහ' වන නිසා ස්වභාවයේ නිදහස් ලෝහ ලෙස පවතී."),
    q("විද්‍යුත් විච්ඡේදක ද්‍රාවණයක අයනවල ආරෝපණ ප්‍රමාණය හා ගලා ගිය විද්‍යුත් ධාරාව වැඩි වන විට ඉලෙක්ට්‍රෝඩවල නිදහස් වන ද්‍රව්‍ය ස්කන්ධයට කුමක් සිදුවේද?", "වැඩි වේ", "අඩු වේ", "ශුන්‍ය වේ", "නොවෙනස්ව පවතී", "මෙය ෆැරඩේගේ විද්‍යුත් විච්ඡේදන නියම මගින් විස්තර කෙරේ."),
    q("සෝඩියම් ක්ලෝරයිඩ් ඝන හා ජලීය HCl අතරින් කුමන අවස්ථාවේදී H⁺ අයන සාදන්නේද?", "ජලීය HCl ද්‍රාවණයේදී පමණි", "වියළි HCl වායුවේදී", "ඝන NaCl වලදී", "කිසිම අවස්ථාවක නැත", "වියළි HCl වායුව ආම්ලික ගුණ නොපෙන්වන්නේ ජලය නොමැතිව H⁺ අයන නිදහස් නොවන නිසාය."),
    q("නිල් හා රතු ලිට්මස් දෙකම වෙනස් නොකරන ලවණ ද්‍රාවණයක් වන්නේ කුමක්ද?", "සෝඩියම් ක්ලෝරයිඩ් (NaCl) ද්‍රාවණය", "සෝඩියම් කාබනේට් (Na₂CO₃)", "ඇමෝනියම් ක්ලෝරයිඩ් (NH₄Cl)", "හයිඩ්‍රොක්ලෝරික් අම්ලය", "ප්‍රබල අම්ලයකින් හා ප්‍රබල භෂ්මයකින් සෑදුණු NaCl ජලයේදී උදාසීන (pH = 7) වේ."),
    q("වීදුරුවක අඩංගු විනාකිරිවල pH අගය ආසන්න වශයෙන් 3 ක් ද දියර සබන් ද්‍රාවණයක pH අගය 9 ක් ද නම් වඩාත් ආම්ලික වන්නේ කුමක්ද?", "විනාකිරි", "දියර සබන්", "දෙකම උදාසීන වේ", "දෙකම සමාන ආම්ලිකතා දරයි", "pH අගය 7 ට වඩා අඩු වන තරමට ආම්ලිකතාව වැඩි වේ."),
    q("වෙළඳපොළේ ඇති සාමාන්‍ය ඇන්ටැසිඩ් පෙතිවල NaHCO₃ (බේකිං සෝඩා) හෝ Mg(OH)₂ අඩංගු වන්නේ කුමන රසායනික ප්‍රතික්‍රියාව සිදු කිරීමටද?", "ආමාශයේ අතිරික්ත HCl අම්ලය උදාසීන කිරීමට", "ආමාශයේ HCl අම්ල සාන්ද්‍රණය වැඩි කිරීමට", "ආමාශයේ ප්‍රෝටීන ආහාර පැසවීම වේගවත් කිරීමට", "තුවාලයකදී රුධිරය ඉක්මනින් කැටි ගැස්වීමට", "ප්‍රතිඅම්ල අතිරික්ත HCl උදාසීන කර වේදනාව සමනය කරයි."),
    q("මැග්නීසියම් 24 g ක් ඔක්සිජන් වායුව සමඟ සම්පූර්ණයෙන් දහනය කළ විට සෑදෙන MgO ස්කන්ධය කීයද? (Mg = 24, O = 16)", "40 g", "24 g", "56 g", "80 g", "2Mg + O₂ → 2MgO; Mg 1 mol (24 g) වලින් MgO 1 mol (24 + 16 = 40 g) සෑදේ."),
    q("සින්ක් ලෝහය සාදන සින්ක් ඔක්සයිඩ් (ZnO) රත් කළ විට කහ පැහැයට හැරී සිසිල් කළ විට නැවත සුදු පැහැයට හැරේ. මෙය කුමන වෙනසක්ද?", "ප්‍රත්‍යාවර්ත භෞතික වෙනසකි", "අප්‍රත්‍යාවර්ත දහනයකි", "වියෝජනයකි", "විස්ථාපනයකි", "ZnO රසායනිකව වෙනස් නොවේ."),
    q("සුළඟ හෝ ජලය නිසා භූගෝලීය පරිසරයේ සිදුවන යකඩ පාලම් විඛාදනය වැළැක්වීමට ගන්නා ප්‍රධාන 'බාධක ක්‍රමය' කුමක්ද?", "තීන්ත, එනැමල් හෝ ග්‍රීස් ආලේප කිරීම", "ලුණු ජලය ඉසීම", "අම්ල ආලේප කිරීම", "තඹ සමඟ සෘජුවම පෑස්සීම", "යකඩ පෘෂ්ඨය ඔක්සිජන් හා තෙතමනය සමඟ ගැටීම මෙමගින් වළකයි."),
    q("තඹ හා සම්බන්ධ කර යකඩ වතුර ටැංකියක් සැදුවහොත් යකඩ මලකඩ කෑමට කුමක් සිදුවේද?", "වැඩි සක්‍රීය යකඩ ඉතා වේගයෙන් මලකඩ කෑමට ලක් වේ", "යකඩ සම්පූර්ණයෙන් ආරක්ෂා වේ", "තඹ ඉක්මනින් මලකඩ කයි", "කිසිදු වෙනසක් නොවේ", "වැඩි සක්‍රීය ලෝහය ඇනෝඩය බවට පත් වී වේගයෙන් ඔක්සිකරණය වේ."),
    q("සල්ෆියුරික් අම්ලය (H₂SO₄) 'රසායන ද්‍රව්‍යවල රජු' ලෙස හඳුන්වනු ලබන අතර එය කාර්මිකව නිපදවන ක්‍රමවේදය කුමක්ද?", "ස්පර්ශ ක්‍රමය (Contact process)", "හේබර් ක්‍රමය", "ඩවුන්ස් ක්‍රමය", "බේයර් ක්‍රමය", "V₂O₅ උත්ප්‍රේරකය යොදා SO₂, SO₃ බවට ඔක්සිකරණය කෙරේ."),
    q("හේබර් ක්‍රමය මගින් නයිට්‍රජන් හා හයිඩ්‍රජන් යොදා කාර්මිකව නිපදවන ප්‍රධාන රසායනික සංයෝගය කුමක්ද?", "ඇමෝනියා (NH₃)", "සල්ෆියුරික් අම්ලය", "සෝඩියම් හයිඩ්‍රොක්සයිඩ්", "ක්ලෝරීන්", "N₂ + 3H₂ ⇌ 2NH₃ (යකඩ උත්ප්‍රේරකය, 450°C, 200 atm)."),
    q("ස්පර්ශ ක්‍රමයේදී SO₂ වායුව SO₃ බවට පරිවර්තනය කිරීමට භාවිත කරන උත්ප්‍රේරකය කුමක්ද?", "වැනේඩියම් පෙන්ටොක්සයිඩ් (V₂O₅)", "ප්ලැටිනම් පමණි", "මැන්ගනීස් ඩයොක්සයිඩ්", "සින්ක් ඔක්සයිඩ්", "V₂O₅ ප්‍රතික්‍රියාව කාර්යක්ෂමව වේගවත් කරයි."),
    q("ජලීය NaOH සහ තනුක H₂SO₄ අම්ලය සම්පූර්ණයෙන් උදාසීන වූ විට සෑදෙන ලවණය කුමක්ද?", "සෝඩියම් සල්ෆේට් (Na₂SO₄)", "සෝඩියම් ක්ලෝරයිඩ්", "සෝඩියම් සල්ෆයිඩ්", "සෝඩියම් නයිට්‍රේට්", "2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O."),
    q("සෝඩියම් හයිඩ්‍රජන් කාබනේට් (NaHCO₃) රත් කළ විට Na₂CO₃ සහ ජල වාෂ්ප සමඟ පිටවන වායුව කුමක්ද?", "කාබන් ඩයොක්සයිඩ් (CO₂)", "ඔක්සිජන් (O₂)", "හයිඩ්‍රජන් (H₂)", "ඇමෝනියා (NH₃)", "කේක් පිපීමේදී CO₂ පිටවීම මීට උදාහරණයකි."),
    q("සාන්ද්‍ර සල්ෆියුරික් අම්ලය ජලය සමඟ තනුක කිරීමේදී අනුගමනය කළ යුතු නිවැරදි ආරක්ෂිත ක්‍රමය කුමක්ද?", "සිසිල් ජලයට කලවම් කරමින් සෙමින් අම්ලය බිංදු බිංදු එක් කිරීම", "සාන්ද්‍ර අම්ලයට එකවර ජලය වත් කිරීම", "රත් කළ ජලයට අම්ලය දැමීම", "වීදුරු පාත්‍රය වසා සෙලවීම", "අම්ලය ජලයේ දියවීම ඉතා තාපදායක බැවින් අම්ලයට ජලය දැමුවහොත් විසි වී පිළිස්සිය හැක."),
    q("කිසියම් ලෝහ කැබැල්ලක් ජලය මත තැබූ විට රිදී පැහැ බෝලයක් ලෙස දිය වී එහා මෙහා දුවමින් දම් පැහැ දැල්ලකින් දැල්වේ. එම ලෝහය කුමක්ද?", "පොටෑසියම් (K)", "සෝඩියම් (Na)", "මැග්නීසියම් (Mg)", "යකඩ (Fe)", "පොටෑසියම් දම් පැහැ දැල්ලකින් ද සෝඩියම් කහ පැහැ දැල්ලකින් ද දැල්වේ."),
    q("සෝඩියම් ක්ලෝරයිඩ් ද්‍රාවණයකට සිල්වර් නයිට්‍රේට් දැමූ විට සෑදෙන AgCl අවක්ෂේපය හිරු එළියේ තැබූ විට කුමන පැහැයකට හැරේද?", "අළු හෝ කළු පැහැයට හැරේ", "තද රතු පැහැයට හැරේ", "දීප්තිමත් කහ පැහැයට හැරේ", "තද නිල් පැහැයට හැරේ", "2AgCl → 2Ag + Cl₂ (ප්‍රකාශ රසායනික වියෝජනය)."),
    q("රසායනික සමීකරණයක් තුලිත කිරීමේදී වෙනස් නොකළ යුතුම කොටස කුමක්ද?", "රසායනික සූත්‍රවල පාදස්ථ අංක", "සංයෝග ඉදිරියෙන් ලියන සංගුණක", "ප්‍රතික්‍රියාවේ ඊතල දිශාව", "ද්‍රව්‍යවල භෞතික අවස්ථා සංකේත", "සංගුණක පමණක් වෙනස් කර දෙපස පරමාණු ගණන සමාන කළ යුතුය."),
    q("පහත කුමන වායුව 'අම්ල වැසි' ඇති වීමට ප්‍රධාන වශයෙන්ම හේතු නොවේද?", "නයිට්‍රජන් (N₂)", "සල්ෆර් ඩයොක්සයිඩ් (SO₂)", "නයිට්‍රජන් ඩයොක්සයිඩ් (NO₂)", "සල්ෆර් ට්‍රයොක්සයිඩ් (SO₃)", "SO₂ හා NO₂ වර්ෂා ජලය සමඟ H₂SO₄ හා HNO₃ සාදයි."),
    q("කිසියම් ද්‍රාවණයක OH⁻ අයන සාන්ද්‍රණය H⁺ අයන සාන්ද්‍රණයට වඩා බොහෝ සෙයින් වැඩි නම් එම ද්‍රාවණය කුමක්ද?", "භාෂ්මික (ක්ෂාරීය) ද්‍රාවණයකි (pH > 7)", "ආම්ලික ද්‍රාවණයකි", "උදාසීන ද්‍රාවණයකි", "විද්‍යුත් අවිච්ඡේද්‍යයකි", "ජලයේදී OH⁻ සාන්ද්‍රණය වැඩි කරන ද්‍රාව්‍ය භෂ්ම වේ."),
    q("මැග්නීසියම් පටියක් තනුක සල්ෆියුරික් අම්ලය සමඟ ප්‍රතික්‍රියා කරන විට MgSO₄ සමඟ පිටවන වායුව කුමක්ද?", "හයිඩ්‍රජන් (H₂)", "ඔක්සිජන් (O₂)", "සල්ෆර් ඩයොක්සයිඩ්", "කාබන් ඩයොක්සයිඩ්", "Mg + H₂SO₄ → MgSO₄ + H₂."),
    q("වීදුරු බීකරයක ඇති කළු CuO කුඩු කිසියම් වායුවක් සමඟ රත් කළ විට රතු-දුඹුරු තඹ ලෝහය සහ ජලය ලැබේ. එම වායුව කුමක්ද?", "හයිඩ්‍රජන් (H₂)", "ඔක්සිජන් (O₂)", "ක්ලෝරීන් (Cl₂)", "නයිට්‍රජන් (N₂)", "CuO + H₂ → Cu + H₂O."),
    q("විදුලි පන්දම් බැටරි (වියළි කෝෂ) භාවිතයේදී ඒවායේ රසායනික ප්‍රතික්‍රියාව තුළින් ලැබෙන ශක්ති පරිවර්තනය කුමක්ද?", "රසායනික ශක්තිය → විද්‍යුත් ශක්තිය", "විද්‍යුත් ශක්තිය → රසායනික ශක්තිය", "තාප ශක්තිය → න්‍යෂ්ටික ශක්තිය", "ආලෝක ශක්තිය → රසායනික ශක්තිය", "ගැල්වැනික කෝෂ රසායනික ශක්තිය විද්‍යුත් ශක්තිය බවට හරවයි.")
  )
}
